// ** Expandable table component
const ExpandableTable = ({ data }) => {
  return (
    <div className='expandable-content p-2'>
      <p>
        <span className='fw-bold'>City:</span> {data.city}
      </p>
      <p>
        <span className='fw-bold'>Experience:</span> {data.experience}
      </p>
      <p className='m-0'>
        <span className='fw-bold'>Post:</span> {data.post}
      </p>
    </div>
  )
}

// ** Table Server Side Column
export const serverSideColumns = [
  {
    sortable: true,
    name: 'Kênh phân phối',
    minWidth: '225px',
    selector: row => row.name
  },
  {
    sortable: true,
    name: 'khu vực',
    minWidth: '250px',
    selector: row => row.region
  },
  {
    sortable: true,
    name: 'Thành phố',
    minWidth: '250px',
    selector: row => row.city
  },
  {
    sortable: true,
    name: 'Ghi chú',
    minWidth: '150px',
    selector: row => row.description
  },
  {
    sortable: true,
    name: 'Người cập nhật',
    minWidth: '150px',
    selector: row => row.userName
  },
  {
    name: 'Hành động',
    minWidth: '150px',
    selector: (row) => {
      console.log(row)
      // const [isShowModalShowCampaign, setIsShowModalShowCampaign] = useState(false)
      const [isShowModalEditDistribution, setIsShowModalEditDistribution] = useState(false)
      const [isShowModalShowDistribution, setIsShowModalShowDistribution] = useState(false)
      const dispatch = useDispatch()
      const handleDeleteDistribution = () => {
        handleQuestion('Bạn muốn tiếp tục?', 'Một khi đã xóa sẽ không thể hoàn tác lại.', (isConfirmed) => {
          if (isConfirmed) {
            dispatch(deleteDistribution({
              id: row.id,
              reloadTable: () => dispatch(
                reloadTable(
                  {
                    getData: (value) => dispatch(
                      getData(value)
                    )
                  }
                )
              )
            }))
          }
        })
      }

      return (
        <Fragment>
          <ModalEditDistribution isShow={isShowModalEditDistribution} setIsShow={setIsShowModalEditDistribution} data={row}/>
          <ModalShowDistribution isShow={isShowModalShowDistribution} setIsShow={setIsShowModalShowDistribution} data={row}/>
          <div className='d-flex '>
              <div>
                <Button.Ripple id={`show${row.id}`} className='btn-icon' color='flat-primary' onClick={() => setIsShowModalShowDistribution(!isShowModalShowDistribution)}>
                  <Eye size={16} />
                </Button.Ripple>
                <UncontrolledTooltip placement='top' target={`show${row.id}`}>
                  Xem chi tiết
                </UncontrolledTooltip>
              </div>
              <div>
                <Button.Ripple id={`edit${row.id}`} className='btn-icon' color='flat-warning' onClick={() => setIsShowModalEditDistribution(!isShowModalEditDistribution)}>
                  <Edit size={16} />
                </Button.Ripple>
                <UncontrolledTooltip placement='top' target={`edit${row.id}`}>
                  Chỉnh sửa
                </UncontrolledTooltip>
              </div>
              <div>
                <Button.Ripple id={`delete${row.id}`} className='btn-icon' color='flat-danger' onClick={() => handleDeleteDistribution()}>
                  <Delete size={16} />
                </Button.Ripple>
                <UncontrolledTooltip placement='top' target={`delete${row.id}`}>
                  Xóa
                </UncontrolledTooltip>
              </div>
          </div>
        </Fragment>
      )
    }
  }
  // ,{
  //   sortable: true,
  //   name: 'Salary',
  //   minWidth: '150px',
  //   selector: row => row.salary
  // }
]


export default ExpandableTable
