// ** React Imports
import { Fragment, useState, useEffect } from 'react'
// ** Utils
import { selectThemeColors } from '@utils'
import classNames from 'classnames'
// ** Reactstrap Imports
import {
  Card,
  Row,
  Col,
  Modal,
  Input,
  Label,
  Button,
  CardBody,
  CardText,
  CardTitle,
  ModalBody,
  ModalHeader,
  FormFeedback
} from 'reactstrap'

// ** Third Party Components
import Select from 'react-select'
import { User, Check, X } from 'react-feather'
import SelectReactCST from '../SelectComponent'
import TextareaCST from '../TextAreaComponent'
import { useDispatch } from 'react-redux'
import { postData } from './store'
import { handleWarning, toastSuccess } from '../../sweetalert'
import { getData, reloadTable } from '../TableComponent/store'


const ModaAddDistribution = (props) => {
  const districts = [
    {value: 'Tây Bắc bộ', label: 'Tây Bắc bộ'},
    {value: 'Đông Bắc bộ', label: 'Đông bắc bộ'},
    {value: 'Đồng bằng sông Hồng', label: 'Đồng bằng sông Hồng'},

    {value: 'Bắc Trung bộ', label: 'Bắc Trung bộ'},
    {value: 'Nam Trung bộ', label: 'Nam Trung bộ'},
    {value: 'Tây Nguyên', label: 'Tây Nguyên'},

    {value: 'Đông Nam bộ', label: 'Đông Nam bộ'},
    {value: 'Đồng bằng sông Cửu Long', label: 'Đồng bằng sông Cửu Long'}
  ]

  const tbbCities = [
    {value: 'tỉnh Hoà Bình', label: 'tỉnh Hòa Bình'}, 
    {value: 'tỉnh Sơn La', label: 'tỉnh Sơn La'}, 
    {value: 'tỉnh Điện Biên', label: 'tỉnh Điện Biên'}, 
    {value: 'tỉnh Lai Châu', label: 'tỉnh Lai Châu'}
  ]
  const dbbCities = [
    {value: 'tỉnh Lào Cai', label: 'tỉnh Lào Cai'},
    {value: 'tỉnh Hà Giang Cao Bằng', label: 'tỉnh Hà Giang Cao Bằng'},
    {value: 'tỉnh Bắc Kạn', label: 'tỉnh Bắc Kạn'},
    {value: 'tỉnh Yên Bái', label: 'tỉnh Yên Bái'}, 
    {value: 'tỉnh Lạng Sơn', label: 'tỉnh Lạng Sơn'}, 
    {value: 'tỉnh Tuyên Quang', label: 'tỉnh Tuyên Quang'}, 
    {value: 'tỉnh Thái Nguyên', label: 'tỉnh Thái Nguyên'}, 
    {value: 'tỉnh Phú Thọ', label: 'tỉnh Phú Thọ'}, 
    {value: 'tỉnh Bắc Giang', label: 'tỉnh Bắc Giang'}, 
    {value: 'tỉnh Quảng Ninh', label: 'tỉnh Quảng Ninh'}
  ]
  const dbshCities = [
    {value: 'thành phố Hà Nội', label: 'thành phố Hà Nội'}, 
    {value: 'thành phố Hải Phòng', label: 'thành phố Hải Phòng'}, 
    {value: 'tỉnh Vĩnh Phúc', label: 'tỉnh Vĩnh Phúc'}, 
    {value: 'tỉnh Bắc Ninh', label: 'tỉnh Bắc Ninh'}, 
    {value: 'tỉnh Hà Nam', label: 'tỉnh Hà Nam'}, 
    {value: 'tỉnh Hải Dương', label: 'tỉnh Hải Dương'}, 
    {value: 'tỉnh Hưng Yên', label: 'tỉnh Hưng Yên'}, 
    {value: 'tỉnh Nam Định', label: 'tỉnh Nam Định'}, 
    {value: 'tỉnh Ninh Bình', label: 'tỉnh Ninh Bình'}, 
    {value: 'tỉnh Thái Bình', label: 'tỉnh Thái Bình'}
  ]
  
  const btbCities = [
    {value: 'tỉnh Thanh Hoá', label: 'tỉnh Thanh Hóa'},
    {value: 'tỉnh Nghệ An', label: 'tỉnh Nghệ An'},
    {value: 'tỉnh Hà Tĩnh', label: 'tỉnh Hà Tĩnh'},
    {value: 'tỉnh Quảng Bình', label: 'tỉnh Quảng Bình'},
    {value: 'tỉnh Quảng Trị', label: 'tỉnh Quảng Trị'}, 
    {value: 'tỉnh Thừa Thiên Huế', label: 'tỉnh Thừa Thiên Huế'}
  ]
  const ntbCities = [
    {value: 'thành phố Đà Nẵng', label: 'thành phố Đà Nẵng'},
    {value: 'tỉnh Quảng Nam', label: 'tỉnh Quảng Nam'}, 
    {value: 'tỉnh Quảng Ngãi', label: 'tỉnh Quảng Ngãi'},
    {value: 'tỉnh Bình Định', label: 'tỉnh Bình Định'}, 
    {value: 'tỉnh Phú Yên', label: 'tỉnh Phú Yên'}, 
    {value: 'tỉnh Khánh Hoà', label: 'tỉnh Khánh Hòa'}, 
    {value: 'tỉnh Ninh Thuận', label: 'tỉnh Ninh Thuận'}, 
    {value: 'tỉnh Bình Thuận', label: 'tỉnh Bình THuận'}
  ]
  const tnCities = [
    {value: 'tỉnh Kon Tum', label: 'tỉnh Kon Tum'},
    {value: 'tỉnh Gia Lai', label: 'tỉnh Gia Lai'}, 
    {value: 'tỉnh Đắc Lắc', label: 'tỉnh Đắc Lắc'}, 
    {value: 'tỉnh Đắc Nông', label: 'tỉnh Đắc Nông'}, 
    {value: 'tỉnh Lâm Đồng', label: 'tỉnh Lâm Đồng'}
  ]

  const dnbCities = [
    {value: 'thành phố Hồ Chí Minh', label: 'thành phố Hồ Chí Minh'}, 
    {value: 'tỉnh Đồng Nai', label: 'tỉnh Đồng Nai'}, 
    {value: 'tỉnh Bà Rịa-Vũng Tàu', label: 'tỉnh Bà Rịa-Vũng Tàu'}, 
    {value: 'tỉnh Bình Dương', label: 'tỉnh Bình Dương'},
    {value: 'tỉnh Bình Phước', label: 'tỉnh Bình Phước'},
    {value: 'tỉnh Tây Ninh', label: 'tỉnh Tây Ninh'}
  ]
  const dbsclCities = [
    { value: 'thành phố Cần Thơ', label: 'thành phố Cần Thơ'},
    { value: 'tỉnh Long An', label: 'tỉnh Long An'},
    { value: 'tỉnh Đồng Tháp', label: 'tỉnh Đồng Tháp'},
    { value: 'tỉnh Tiền Giang', label: 'tỉnh Tiền Giang'}, 
    { value: 'tỉnh An Giang', label: 'tỉnh An Giang'}, 
    { value: 'tỉnh Bến Tre', label: 'tỉnh Bến Tre'}, 
    { value: 'tỉnh Vĩnh Long', label: 'tỉnh Vĩnh Long'}, 
    { value: 'tỉnh Trà Vinh', label: 'tỉnh Trà Vinh'}, 
    { value: 'tỉnh Hậu Giang', label: 'tỉnh Hậu Giang'}, 
    { value: 'tỉnh Kiên Giang', label: 'tỉnh Kiên Giang'}, 
    { value: 'tỉnh Sóc Trăng', label: 'tỉnh Sóc Trăng'}, 
    { value: 'tỉnh Bạc Liêu', label: 'tỉnh Bạc Liêu'}, 
    { value: 'tỉnh Cà Mau', label: 'tỉnh Cà Mau'}
  ]
  const {isShow, setIsShow, data} = props
  // const [isEditFunc, setIsEditFunc] = useState(false)
  const [cities, setCities] = useState([])

  const [nameDistribution, setNameDistribution] = useState(data.name)
  const [districtChoice, setDistrictChoice] = useState({
    value: data.region, label: data.region
  })
  const [cityChoice, setCityChoice] = useState({
    value: data.city, label: data.city
  })
  const [description, setDescription] = useState(data.description)

  
  const handleChangeDistrict = (district) => {
    // console.log(district)
    setDistrictChoice(district)
    setCityChoice({
      value: '', label: ''
    })
    // console.log(districtChoice)
    switch (district.value) {
      case 'Tây Bắc bộ':
        setCities(tbbCities)
        break
        case 'Đông Bắc bộ':
        setCities(dbbCities)
        break
        case 'Đồng bằng sông Hồng':
          setCities(dbshCities)
          break
          case 'Bắc Trung bộ':
            setCities(btbCities)
            break
      case 'Nam Trung bộ':
        setCities(ntbCities)
        break
        case 'Tây Nguyên':
          setCities(tnCities)
          break
          case 'Đông Nam bộ':
            setCities(dnbCities)
            break
            case 'Đồng bằng sông Cửu Long':
              setCities(dbsclCities)
              break
            }
  }

  const handleChangeCity = (city) => {
    setCityChoice(city)
  }
  
  useEffect(() => {
    handleChangeDistrict(districtChoice)
    handleChangeCity({
      value: data.city, label: data.city
    })
  }, [data])
  
  // const state = useSelector(state => state.addDistribution)
  const handleStateModal = (value) => {
      // console.log(value)
      if (value) {
      setIsShow(!isShow)
      toastSuccess("Sửa thành công")
    } else {
      handleWarning("Cảnh báo", 'Quá trình chỉnh sửa kênh phân phối không thành công')
    }
  }

  const dispatch = useDispatch()
  const handleEditDistribution = () => {
    try {
      if (nameDistribution !== '' && districtChoice.value !== '' && cityChoice.value !== '') {
        dispatch(postData(
          {
            id: data.id,
            body: {
              name: nameDistribution,
              region: districtChoice.value,
              city: cityChoice.value,
              description
            },
            changeStateModal: (value) => handleStateModal(value),
            reloadTable: () => dispatch(
              reloadTable( 
                {
                  getData: (value) => dispatch(getData(value))
                }
              )
            )
          }
        ))
      }
    } catch (error) {
    }
  }
  return (
    <Fragment>
      <Modal isOpen={isShow} className='modal-dialog-centered modal-lg'>
        <ModalHeader className='bg-transparent' toggle={() => setIsShow(!isShow)}></ModalHeader>
        <ModalBody className='px-sm-5 mx-50 pb-5'>
          <div className='text-center mb-2'>
            <h1 className='mb-1 fw-bold'>Chỉnh sửa kênh phân phối</h1>
            <p>Bạn có thể chỉnh sửa thông tin một kênh phân phối tại đây.</p>
          </div>
          <Row className='gy-1 pt-75'>
            <Col xs="12">
              {/* <FormAddCampain /> */}
              <Label className='form-label'>
                Tên kênh phân phối
              </Label>
              <Input type='text' invalid={nameDistribution === ''} value={nameDistribution} onChange={(e) => setNameDistribution(e.target.value)}/>
              {(nameDistribution !== null) && <FormFeedback> Bạn chưa nhập tên kênh phân phối </FormFeedback>}
            </Col>
            <Col sm="6" xs="12">
              <Label className='form-label'>
                Khu vực
              </Label>
              <Select
                name='district'
                options={districts}
                classNamePrefix='select'
                theme={selectThemeColors}
                placeholder='Chọn...'
                value={districtChoice}
                onChange={(e) => handleChangeDistrict(e)}
                className={classNames('react-select', { 'is-invalid': districtChoice.value === ''})}
              />
              {(districtChoice.value === '') && <FormFeedback> Bạn chưa chọn khu vực </FormFeedback>}
              {/* <SelectReactCST label="Khu vực" data={districts} valueChoice={districtChoice} onSelectChanged={(value) => handleChangeDistrict(value)}/> */}
            </Col>
            <Col sm="6" xs="12">
              <Label className='form-label'>
                Tỉnh, thành phố
              </Label>
              <Select
                name='provinceCity'
                options={cities}
                classNamePrefix='select'
                theme={selectThemeColors}
                placeholder='Chọn...'
                value={cityChoice}
                onChange={(e) => handleChangeCity(e)}
                className={classNames('react-select', { 'is-invalid': cityChoice.value === ''})}
              />
              {(cityChoice.value === '') && <FormFeedback> Bạn chưa chọn tỉnh, thành phố </FormFeedback>}
              {/* <SelectReactCST label="Tỉnh, thành phố" data={cities} valueChoice={cityChoice} onSelectChanged={(value) => handleChangeCity(value)}/> */}
            </Col>
            <Col xs="12">
              <TextareaCST label="Ghi chú" value={description} onChange={(value) => setDescription(value)}/>
            </Col>
            <Col xs={12} className='text-center mt-2 pt-50'>
              <Button className='me-1' color={'success'} onClick={handleEditDistribution}>
                Lưu lại
              </Button>
              <Button type='reset' color='secondary' outline onClick={() => setIsShow(false)}>
                Trở lại
              </Button>
            </Col>
          </Row>
        </ModalBody>
      </Modal>
    </Fragment>
  )
}

export default ModaAddDistribution
