// ** React Imports
import { Fragment, useState, useEffect, memo, useRef } from 'react'

// ** Table Columns
import { serverSideColumns } from './data'

// ** Store & Actions
import { getData, updateShowLoading, updateSearch, deleteDistributions, reloadTable } from './store'
import { useSelector, useDispatch } from 'react-redux'

// ** Third Party Components
import ReactPaginate from 'react-paginate'
import { ChevronDown, Delete, Home, Plus } from 'react-feather'
import DataTable from 'react-data-table-component'
// import ModalAddAgent from '../ModalAddAgentComponent'
import ModaAddDistribution from '../ModalAddDistributionComponent'
// ** Reactstrap Imports
import { Card, CardHeader, CardTitle, Input, Label, Row, Col, Button, Spinner } from 'reactstrap'
import { handleQuestion } from '../../sweetalert'

const DataTableServerSide = () => {
  // ** Store Vars
  const dispatch = useDispatch()
  const store = useSelector(state => state.tableDistribution)
  const isShowLoading = store.isShowLoading

  // console.log('ishow', store, updateShowLoading)
  // ** States
  const [currentPage, setCurrentPage] = useState(1)
  const [rowsPerPage, setRowsPerPage] = useState(7)
  const [searchValue, setSearchValue] = useState('')
  // const [isShowLoading, setIsShowLoading] = useState(false)

  // ** Get data on mount
  useEffect(() => {
    dispatch(
      getData({
        page: currentPage,
        perPage: rowsPerPage,
        q: searchValue,
        // showLoading: (value) => setIsShowLoading(value)
        showLoading: (value) => dispatch(updateShowLoading(value)) 
      })
    )
  }, [dispatch])

  let timeRef = useRef()

  const dispatchHandleFilter = e => {
    dispatch(
      updateSearch(e.target.value)
    )
    dispatch(
      getData({
        page: currentPage,
        perPage: rowsPerPage,
        q: e.target.value,
        showLoading: (value) => dispatch(updateShowLoading(value)) 
        // showLoading: (value) => setIsShowLoading(value)
      })
    )
  }
  // ** Function to handle filter
  const handleFilter = e => {
    console.log("toan")
    clearTimeout(timeRef)
    setSearchValue(e.target.value)
    dispatch(updateShowLoading(true))
    timeRef = setTimeout(() => {
      dispatchHandleFilter(e)
    }, 200)
  }

  // ** Function to handle Pagination and get data
  const handlePagination = page => {
    console.log('page', page)
    dispatch(
      getData({
        page: page.selected + 1,
        perPage: rowsPerPage,
        q: searchValue,
        showLoading: (value) => dispatch(updateShowLoading(value)) 
      })
    )
    setCurrentPage(page.selected + 1)
  }

  // ** Function to handle per page
  const handlePerPage = e => {
    dispatch(
      getData({
        page: currentPage,
        perPage: parseInt(e.target.value),
        q: searchValue,
        showLoading: (value) => dispatch(updateShowLoading(value)) 
      })
    )
    setRowsPerPage(parseInt(e.target.value))
  }

  // ** Custom Pagination
  const CustomPagination = () => {
    console.log(store.total)
    // const count = Math.ceil(store.total / rowsPerPage)

    return (
      <ReactPaginate
        previousLabel={''}
        nextLabel={''}
        breakLabel='...'
        // pageCount={Math.ceil(count) || 1}
        pageCount={store.total}
        marginPagesDisplayed={2}
        pageRangeDisplayed={2}
        activeClassName='active'
        forcePage={currentPage !== 0 ? currentPage - 1 : 0}
        onPageChange={page => handlePagination(page)}
        pageClassName='page-item'
        breakClassName='page-item'
        nextLinkClassName='page-link'
        pageLinkClassName='page-link'
        breakLinkClassName='page-link'
        previousLinkClassName='page-link'
        nextClassName='page-item next-item'
        previousClassName='page-item prev-item'
        containerClassName={
          'pagination react-paginate separated-pagination pagination-sm justify-content-end pe-1 mt-1'
        }
      />
    )
  }

  // ** Table data to render
  const dataToRender = () => {
    // return []
    console.log(store.data)
    // return store.data
    const filters = {
      q: searchValue
    }

    const isFiltered = Object.keys(filters).some(function (k) {
      return filters[k].length > 0
    })

    if (store.data.length > 0) {
      return store.data
    } else if (store.data.length === 0 && isFiltered) {
      return []
    } else {
      // return store.allData
      return store.allData.slice(0, rowsPerPage)
    }
  }

  // state
  const [isShowAddCampain, setIsShowAddCampain] = useState(false)
  const [selectedRows, setSelectedRows] = useState([])
  const [toggleClearSeRows, setToggleClearSeRows] = useState(false)
  const handleSelectedRowChange = (state) => {
    console.log(state)
    setSelectedRows(state.selectedRows)
  }

  const handleDeleteSelectedRows = () => {
    handleQuestion("Bạn muốn tiếp tục?", "Việc xóa các kênh phân phối sẽ không thể hoàn tác lại", (isConfirmed) => {
      if (isConfirmed) {
        dispatch(
          deleteDistributions({
            data: selectedRows,
            reloadTable: () => dispatch(
              reloadTable({
                getData: (params) => dispatch(getData(params))
              })
            ) 
          })
        )
        .then(() => {
          setToggleClearSeRows(!toggleClearSeRows)
          setSelectedRows([])
        })
      }
    })
  }

  return (
    <Fragment>
      <ModaAddDistribution isShow={isShowAddCampain} setIsShow={setIsShowAddCampain} />
      {/* <ModalAddAgent isShow={isShowAddAgent} setIsShow={setIsShowAddAgent}/> */}
      <Card>
        <CardHeader className='border-bottom'>
          <CardTitle tag='h4'>Danh sách kênh phân phối</CardTitle>
        </CardHeader>
        <Row>
          <Col sm="6">
            <Button.Ripple color='primary' className='m-1' onClick={() => setIsShowAddCampain(!isShowAddCampain)}>
              <Plus size={14} />
              <span className='align-middle ms-25'>Thêm kênh phân phối</span>
            </Button.Ripple>
          </Col>
        </Row>
        <Row className='mx-0 mt-1 mb-50'>
          <Col sm='6'>
            <div className='d-flex align-items-center'>
              <Label for='sort-select'>Hiển thị</Label>
              <Input
                className='dataTable-select'
                type='select'
                id='sort-select'
                value={rowsPerPage}
                onChange={e => handlePerPage(e)}
              >
                <option value={7}>7</option>
                <option value={10}>10</option>
                <option value={25}>25</option>
                <option value={50}>50</option>
                <option value={75}>75</option>
                <option value={100}>100</option>
              </Input>
              <Label for='sort-select'>hàng</Label>
            </div>
          </Col>
          <Col className='d-flex align-items-center justify-content-sm-end mt-sm-0 mt-1' sm='6'>
            <div className='me-1'>
              {
                (isShowLoading) && (
                  <Spinner color='primary' />
                )
              }  
            </div>
            <Label className='me-1' for='search-input'>
              Tìm kiếm
            </Label>
            <Input
              className='dataTable-filter'
              type='text'
              bsSize='sm'
              id='search-input'
              value={searchValue}
              onChange={handleFilter}
            />
          </Col>
        </Row>
        {
          selectedRows.length > 0 && (
            <Row>
              <Col sm="6">
                <Button.Ripple color='danger' outline className='m-1' onClick={() => handleDeleteSelectedRows()}>
                  <Delete size={14} />
                  <span className='ms-1 align-middle ms-25'>Xóa các kênh phân phối</span>
                </Button.Ripple>
              </Col>
            </Row>
          )
        }
        <div className='react-dataTable'>
          <DataTable
            noHeader
            pagination
            paginationServer
            className='react-dataTable'
            columns={serverSideColumns}
            selectableRows
            onSelectedRowsChange={handleSelectedRowChange}
            clearSelectedRows={toggleClearSeRows}
            sortIcon={<ChevronDown size={10} />}
            paginationComponent={CustomPagination}
            data={dataToRender()}
          />
        </div>
      </Card>
    </Fragment>
  )
}

export default memo(DataTableServerSide)
