// ** React Imports
import { Fragment } from 'react'

// ** Reactstrap Imports
import {
  Card,
  Row,
  Col,
  Modal,
  Input,
  Label,
  Button,
  CardBody,
  CardText,
  CardTitle,
  ModalBody,
  ModalHeader,
  FormFeedback
} from 'reactstrap'

// ** Third Party Components
import Select from 'react-select'
import { User, Check, X } from 'react-feather'
import SelectReactCST from '../SelectComponent'
import TextareaCST from '../TextAreaComponent'

const ModaAddDistribution = (props) => {
  
  const {isShow, setIsShow, data} = props
  return (
    <Fragment>
      <Modal isOpen={isShow} className='modal-dialog-centered modal-lg' toggle={() => setIsShow(!isShow)}>
        <ModalHeader className='bg-transparent' toggle={() => setIsShow(!isShow)}></ModalHeader>
        <ModalBody className='px-sm-5 mx-50 pb-5'>
          <div className='text-center mb-2'>
            <h1 className='mb-1 fw-bold'>Xem kênh phân phối</h1>
            <p>Bạn có thể xem chi tiết thông tin một kênh phân phối tại đây.</p>
          </div>
          <Row className='gy-1 pt-75'>
            <Col xs="12">
              {/* <FormAddCampain /> */}
              <Label className='form-label'>
                Tên kênh phân phối
              </Label>
              <Input type='text' style={{textColor: 'black'}} value={data.name}/>
              {/* <Input disabled type='text' style={{textColor: 'black'}} value={nameDistribution} onChange={(e) => setNameDistribution(e.target.value)} isDisabled/> */}
            </Col>
            <Col sm="6" xs="12">
              <Label className='form-label'>
                Khu vực
              </Label>
              <Input  type='text' style={{textColor: 'black'}} value={data.region}/>
              {/* <SelectReactCST disabled={true} label="Khu vực" data={districts} valueChoice={districtChoice} onSelectChanged={(value) => handleChangeDistrict(value)}/> */}
            </Col>
            <Col sm="6" xs="12">
              <Label className='form-label'>
                Tỉnh, thành phố
              </Label>
              <Input  type='text' style={{textColor: 'black'}} value={data.city}/>
              {/* <SelectReactCST disabled={true} label="Tỉnh, thành phố" data={cities} valueChoice={cityChoice} onSelectChanged={(value) => handleChangeCity(value)}/> */}
            </Col>
            <Col xs="12">
              <TextareaCST disabled={true} label="Ghi chú" value={data.description} onChange={(value) => setDescription(value)}/>
            </Col>
            <Col xs={12} className='text-center mt-2 pt-50'>

              <Button type='reset' color='secondary' outline onClick={() => setIsShow(false)}>
                Trở lại
              </Button>
            </Col>
          </Row>
        </ModalBody>
      </Modal>
    </Fragment>
  )
}

export default ModaAddDistribution
